import assert from 'node:assert/strict'
import { spawn, execFileSync } from 'node:child_process'
import { existsSync, rmSync, writeFileSync } from 'node:fs'

const PROD='https://osrm.github.io/catfood_web/'
const DEPLOY_SHA='6f457a6d3ab3830c0d2d4e2a414859a79aa4b5ca'
const TARGET='Pacific Catch'
const sleep=(ms)=>new Promise((r)=>setTimeout(r,ms))

class Cdp{constructor(url){this.url=url;this.ws=null;this.id=1;this.pending=new Map()}async connect(){this.ws=new WebSocket(this.url);await new Promise((res,rej)=>{const t=setTimeout(()=>rej(new Error('ws timeout')),15000);this.ws.addEventListener('open',()=>{clearTimeout(t);res()},{once:true});this.ws.addEventListener('error',()=>rej(new Error('ws error')),{once:true})});this.ws.addEventListener('message',(e)=>{const m=JSON.parse(e.data);if(!m.id)return;const p=this.pending.get(m.id);if(!p)return;this.pending.delete(m.id);m.error?p.reject(new Error(m.error.message)):p.resolve(m.result)});for(const m of ['Page.enable','Runtime.enable'])await this.send(m)}send(method,params={}){const id=this.id++;return new Promise((res,rej)=>{this.pending.set(id,{resolve:res,reject:rej});this.ws.send(JSON.stringify({id,method,params}))})}async eval(expression){const r=await this.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result?.value}async wait(expression,label,ms=45000){const end=Date.now()+ms;while(Date.now()<end){try{if(await this.eval(`Boolean(${expression})`))return}catch{}await sleep(120)}throw new Error(`timeout ${label}`)}async nav(url){await this.send('Page.navigate',{url});await this.wait(`document.readyState==='complete'`,'ready');await this.wait(`document.querySelector('#root')&&document.body.innerText.length>0`,'root')}async viewport(w,h){await this.send('Emulation.setDeviceMetricsOverride',{width:w,height:h,deviceScaleFactor:1,mobile:false})}async shot(path){const r=await this.send('Page.captureScreenshot',{format:'png',fromSurface:true,captureBeyondViewport:false});writeFileSync(path,Buffer.from(r.data,'base64'))}close(){try{this.ws?.close()}catch{}}}
async function launch(){const bin='/usr/bin/google-chrome';assert.ok(existsSync(bin));const version=execFileSync(bin,['--version'],{encoding:'utf8'}).trim();const port=9940+(process.pid%40);const dir=`/tmp/catfood-label-postdeploy-${process.pid}`;rmSync(dir,{recursive:true,force:true});const proc=spawn(bin,['--headless=new','--no-sandbox','--disable-dev-shm-usage','--disable-gpu',`--remote-debugging-port=${port}`,`--user-data-dir=${dir}`,'about:blank'],{stdio:'ignore'});for(let i=0;i<200;i++){try{const pages=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json();const p=pages.find(x=>x.type==='page'&&x.webSocketDebuggerUrl);if(p)return{version,proc,dir,c:new Cdp(p.webSocketDebuggerUrl)}}catch{}await sleep(100)}throw new Error('chrome start timeout')}
async function clickText(c,selector,text){const ok=await c.eval(`(()=>{const n=[...document.querySelectorAll(${JSON.stringify(selector)})].find(x=>x.textContent?.includes(${JSON.stringify(text)}));if(!n)return false;n.scrollIntoView({block:'center'});n.click();return true})()`);assert.ok(ok,`missing click target: ${text}`);await sleep(180)}
async function setInput(c,selector,value){const ok=await c.eval(`(()=>{const n=document.querySelector(${JSON.stringify(selector)});if(!n)return false;const s=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;s.call(n,${JSON.stringify(value)});n.dispatchEvent(new Event('input',{bubbles:true}));return true})()`);assert.ok(ok,`missing input ${selector}`);await sleep(250)}
async function openTargetCandidate(c){for(let i=0;i<25;i++){const found=await c.eval(`[...document.querySelectorAll('.switch-candidate-row')].some(x=>x.textContent?.includes(${JSON.stringify(TARGET)}))`);if(found){await clickText(c,'.switch-candidate-row',TARGET);return}const more=await c.eval(`Boolean(document.querySelector('.switch-candidate-list .load-more'))`);if(!more)break;await clickText(c,'.switch-candidate-list .load-more','제품 더 보기')}throw new Error('target candidate not found')}
async function checkExplore(c){await c.viewport(1440,1000);await c.nav(PROD+'?view=workspace&applied=1&recipeDetails=skipjack_tuna');await c.wait(`document.querySelectorAll('.research-result-card').length>0`,'explore results');const state=await c.eval(`(()=>({url:location.href,criteria:[...document.querySelectorAll('.criteria-chips span')].map(x=>x.textContent?.trim()),selected:[...document.querySelectorAll('.selected-refinement')].map(x=>x.textContent?.trim()),relations:[...document.querySelectorAll('.result-relations')].slice(0,3).map(x=>x.innerText.replace(/\\s+/g,' ').trim())}))()`);assert.ok(state.url.includes('recipeDetails=skipjack_tuna'),'raw key missing');assert.ok(state.criteria.some(x=>x?.includes('가다랑어(Skipjack tuna)')),'Korean skipjack label missing');assert.ok(state.selected.some(x=>x?.includes('가다랑어(Skipjack tuna)')),'selected Korean label missing');await c.shot('qa-artifacts/postdeploy-explore-skipjack.png');return state}
async function checkSwitch(c){await c.viewport(1440,1000);await c.nav(PROD+'?view=workspace&mode=switch');await c.wait(`document.querySelector('.switch-find-search input')`,'switch search');await setInput(c,'.switch-find-search input','로얄캐닌');await c.wait(`document.querySelectorAll('.switch-find-result').length>0`,'current results');await c.eval(`document.querySelector('.switch-find-result')?.click()`);await c.wait(`document.querySelector('.switch-current-preview')`,'current preview');await clickText(c,'.switch-current-preview button','이 제품을 현재 사료로 선택');await c.wait(`document.querySelector('.switch-sku-list')`,'sku');await clickText(c,'.switch-step-actions button','사용 규격을 모르겠어요');await c.wait(`[...document.querySelectorAll('h1')].some(x=>x.textContent?.includes('무엇을 바꾸고 싶나요'))`,'change');await clickText(c,'button','특별히 바꾸고 싶은 점 없음');await clickText(c,'.switch-step-actions button','다음');await c.wait(`[...document.querySelectorAll('h1')].some(x=>x.textContent?.includes('무엇을 그대로 유지할까요'))`,'keep');await clickText(c,'.switch-step-actions button','후보 제품 보기');await c.wait(`document.querySelector('.switch-candidate-list')`,'candidates');await openTargetCandidate(c);await c.wait(`document.querySelector('.switch-candidate-inspector')`,'inspector');const value=await c.eval(`(()=>{const dt=[...document.querySelectorAll('.switch-candidate-inspector dt')].find(x=>x.textContent?.trim()==='세부 레시피');if(!dt)return null;const dd=dt.parentElement?.querySelector('dd');dt.parentElement?.scrollIntoView({block:'center'});return dd?.textContent?.trim()||null})()`);assert.ok(value?.includes('호키'),'Korean hoki label missing');assert.ok(!value?.match(/(^| · )hoki( · |$)/),'raw hoki fallback remains');await sleep(160);await c.shot('qa-artifacts/postdeploy-switch-hoki.png');return{value,url:await c.eval('location.href')}}

const {version,proc,dir,c}=await launch();const report={browserVersion:version,deployedSha:DEPLOY_SHA,base:PROD}
try{await c.connect();const explore=await checkExplore(c);const sw=await checkSwitch(c);writeFileSync('qa-artifacts/report.json',JSON.stringify({...report,explore,switch:sw},null,2));console.log('RECIPE_LABEL_POSTDEPLOY PASS')}catch(e){writeFileSync('qa-artifacts/report.json',JSON.stringify({...report,error:String(e),url:await c.eval('location.href').catch(()=>null),screen:await c.eval('document.body.innerText').catch(()=>null)},null,2));await c.shot('qa-artifacts/failure-current-screen.png').catch(()=>{});throw e}finally{c.close();proc.kill('SIGTERM');await sleep(200);if(proc.exitCode==null)proc.kill('SIGKILL');rmSync(dir,{recursive:true,force:true})}
